(2,	1,	'upload-1',	'a:1:{s:4:\"file\";a:5:{s:7:\"success\";b:1;s:9:\"file_name\";s:25:\"QyV7cC9rp0fk-fondouni.png\";s:8:\"file_url\";s:123:\"http://localhost/wp-content/uploads/forminator/153_9961fbcca049ae044d0e1e7a1044cf71/uploads/QyV7cC9rp0fk-fondouni.png\";s:7:\"message\";s:0:\"\";s:9:\"file_path\";s:148:\"C:/Users/HpAle/Local Sites/isiquizy2/app/public/wp-content/uploads/forminator/153_9961fbcca049ae044d0e1e7a1044cf71/uploads/QyV7cC9rp0fk-fondouni.png\";}}',	'2025-05-21 14:53:21',	'0000-00-00 00:00:00'),
