(44,	7,	'upload-2',	'a:1:{s:4:\"file\";a:3:{s:7:\"success\";b:1;s:8:\"file_url\";a:2:{i:0;s:157:\"http://localhost/wp-content/uploads/forminator/153_9961fbcca049ae044d0e1e7a1044cf71/uploads/hRJDv5ArOgTQ-2.3.7-packet-tracer-navigate-the-ios_es-XL.pdf\";i:1;s:161:\"http://localhost/wp-content/uploads/forminator/153_9961fbcca049ae044d0e1e7a1044cf71/uploads/uGPhJ3xqvXcm-1.5.7-packet-tracer-network-representation_es.docx\";}s:9:\"file_path\";a:2:{i:0;s:182:\"C:/Users/HpAle/Local Sites/isiquizy2/app/public/wp-content/uploads/forminator/153_9961fbcca049ae044d0e1e7a1044cf71/uploads/hRJDv5ArOgTQ-2.3.7-packet-tracer-navigate-the-ios_es-XL.pdf\";i:1;s:186:\"C:/Users/HpAle/Local Sites/isiquizy2/app/public/wp-content/uploads/forminator/153_9961fbcca049ae044d0e1e7a1044cf71/uploads/uGPhJ3xqvXcm-1.5.7-packet-tracer-network-representation_es.docx\";}}}',	'2025-05-23 23:32:13',	'0000-00-00 00:00:00'),
